      const createHTMLDocument = implementation?.createHTMLDocument;
      if (typeof createHTMLDocument !== "function") return html;
      const htmlDoc = createHTMLDocument.call(implementation, "");
      const container = htmlDoc.createElement("div");
      container.innerHTML = html;
