  function registerReaderToolbarButton() {
    const pluginID = config.addonID;
    const createToolbarButton = (doc2, reader) => {
      const buttonContainer = doc2.createElement("div");
      buttonContainer.className = "ai-butler-toolbar-container";
      buttonContainer.style.cssText = `
      display: flex;
      align-items: center;
      margin-left: 8px;
    `;
      const button = doc2.createElement("button");
      button.className = "toolbar-button ai-butler-reader-chat-btn";
      button.innerHTML = `\u{1F916}`;
      button.title = "AI \u7BA1\u5BB6 - \u4E0E AI \u5BF9\u8BDD\u8BA8\u8BBA\u5F53\u524D\u8BBA\u6587";
      button.style.cssText = `
      padding: 4px 8px;
      border: none;
      border-radius: 4px;
      background: transparent;
      color: inherit;
      cursor: pointer;
      font-size: 16px;
      transition: all 0.2s ease;
    `;
      button.addEventListener("mouseenter", () => {
        button.style.background = "rgba(0, 0, 0, 0.08)";
      });
      button.addEventListener("mouseleave", () => {
        button.style.background = "transparent";
      });
      button.addEventListener("click", async () => {
        try {
          const readerItem = reader._item;
          if (!readerItem) {
            new ztoolkit.ProgressWindow("AI Butler", {
              closeOnClick: true,
              closeTime: 3e3
            }).createLine({
              text: "\u65E0\u6CD5\u83B7\u53D6\u5F53\u524D\u6587\u732E\u4FE1\u606F",
              type: "error"
            }).show();
            return;
          }
          let targetItemId;
          if (readerItem.isAttachment()) {
            const parentId = readerItem.parentItemID;
            if (!parentId) {
              new ztoolkit.ProgressWindow("AI Butler", {
                closeOnClick: true,
                closeTime: 3e3
              }).createLine({
                text: "\u8BE5 PDF \u6CA1\u6709\u5173\u8054\u7684\u7236\u6761\u76EE",
                type: "error"
              }).show();
              return;
            }
            targetItemId = parentId;
          } else {
            targetItemId = readerItem.id;
          }
          await handleOpenAIChat(targetItemId);
        } catch (error) {
          ztoolkit.log("[AI-Butler] Reader \u5DE5\u5177\u680F\u6309\u94AE\u70B9\u51FB\u5931\u8D25:", error);
          new ztoolkit.ProgressWindow("AI Butler", {
            closeOnClick: true,
            closeTime: 3e3
          }).createLine({
            text: `\u6253\u5F00\u5931\u8D25: ${error.message || error}`,
            type: "error"
          }).show();
        }
      });
      buttonContainer.appendChild(button);
      return buttonContainer;
    };
    try {
      Zotero.Reader.registerEventListener(
        "renderToolbar",
        (event) => {
          const { reader, doc: doc2, append } = event;
          const buttonContainer = createToolbarButton(doc2, reader);
          append(buttonContainer);
        },
        pluginID
      );
      setTimeout(() => {
        try {
          const readers = Zotero.Reader._readers || [];
          for (const reader of readers) {
            if (!reader?._iframeWindow?.document) continue;
            const doc2 = reader._iframeWindow.document;
            const toolbar = doc2.querySelector(".toolbar");
            if (!toolbar) continue;
            if (toolbar.querySelector(".ai-butler-toolbar-container")) continue;
            const buttonContainer = createToolbarButton(doc2, reader);
            toolbar.appendChild(buttonContainer);
          }
          ztoolkit.log(
            `[AI-Butler] \u5DF2\u4E3A ${readers.length} \u4E2A\u5DF2\u6253\u5F00\u7684 Reader \u6DFB\u52A0\u5DE5\u5177\u680F\u6309\u94AE`
          );
        } catch (err) {
          ztoolkit.log("[AI-Butler] \u5904\u7406\u5DF2\u6253\u5F00\u7684 Reader \u5931\u8D25:", err);
        }
      }, 1e3);
      ztoolkit.log("[AI-Butler] Reader \u5DE5\u5177\u680F\u6309\u94AE\u5DF2\u6CE8\u518C");
    } catch (error) {
      ztoolkit.log("[AI-Butler] \u6CE8\u518C Reader \u5DE5\u5177\u680F\u6309\u94AE\u5931\u8D25:", error);
    }
  }
